function bestDistinctSum(nums: number[]): number {
  const vals = [...new Set(nums)];
  let best = -Infinity;
  for (let mask = 1; mask < 1 << vals.length; mask++) {
    let sum = 0;
    for (let i = 0; i < vals.length; i++) if (mask & (1 << i)) sum += vals[i];
    best = Math.max(best, sum);
  }
  return best;
}

