class Solution:
    def bestDistinctSum(self, nums: List[int]) -> int:
        vals = list(set(nums))
        best = -math.inf
        for mask in range(1, 1 << len(vals)):
            best = max(best, sum(v for i, v in enumerate(vals) if mask >> i & 1))
        return best

