function bestDistinctSum(nums: number[]): number {
  let top = nums[0];
  for (const x of nums) if (x > top) top = x;
  if (top <= 0) return top;
  let sum = 0;
  for (const x of new Set(nums)) if (x > 0) sum += x;
  return sum;
}

